values ('bbbb0001-0000-4000-8000-00000000000c', 'en', null, 'Discrete Mathematics', 'The mathematics that computer science actually runs on — logic and proof, sets and functions, counting, number theory, and graphs. Structure adapted from MIT OpenCourseWare 6.042 Mathematics for Computer Science (CC BY-NC-SA 4.0).', null, 'foundations', 12, true, 'math', '{bbbb0001-0000-4000-8000-000000000003}')
